#include "FaceRenderer.h"
#include <math.h>
#include <algorithm>
using namespace FaceConfig;
static constexpr uint16_t INK=0x0841, WHITE=0xffff;
static uint16_t rgb(int r,int g,int b){return ((r&248)<<8)|((g&252)<<3)|(b>>3);}
static uint16_t blend(uint16_t a,uint16_t b,float u){u=fmaxf(0,fminf(1,u));int r=lroundf(((a>>11)&31)*(1-u)+((b>>11)&31)*u);int g=lroundf(((a>>5)&63)*(1-u)+((b>>5)&63)*u);int v=lroundf((a&31)*(1-u)+(b&31)*u);return (r<<11)|(g<<5)|v;}
static float mix(float a,float b,float t){return a+(b-a)*t;}
bool FaceRenderer::begin(){sprite.setColorDepth(16);if(!sprite.createSprite(WIDTH,STRIP))return false;for(int y=0;y<HEIGHT;y++){float d=112*112-(y-120)*(y-120);if(d<0){left[y]=240;right[y]=-1;}else{int s=(int)sqrtf(d);left[y]=120-s;right[y]=120+s;}}return true;}
void FaceRenderer::line(int a,int b,int y,uint16_t c){if(y<offset||y>=offset+STRIP||y<0||y>=HEIGHT)return;a=(std::max)(a,(int)left[y]);b=(std::min)(b,(int)right[y]);if(b>=a)sprite.drawFastHLine(a,y-offset,b-a+1,c);}
void FaceRenderer::ellipse(float x,float y,float rx,float ry,uint16_t c){if(rx<=0||ry<=0)return;int lo=(std::max)(offset,(int)ceilf(y-ry)),hi=(std::min)(offset+STRIP-1,(int)floorf(y+ry));for(int yy=lo;yy<=hi;yy++){float d=(yy-y)/ry;float w=rx*sqrtf(fmaxf(0,1-d*d));line(ceilf(x-w),floorf(x+w),yy,c);}}
void FaceRenderer::curve(float x0,float y0,float x1,float y1,float x2,float y2,float width,uint16_t c){float r=width*.5f;if(fmaxf(y0,fmaxf(y1,y2))+r<offset||fminf(y0,fminf(y1,y2))-r>=offset+STRIP)return;int n=(std::max)(8,(int)(hypotf(x1-x0,y1-y0)+hypotf(x2-x1,y2-y1)));for(int i=0;i<=n;i++){float t=(float)i/n,u=1-t;ellipse(u*u*x0+2*u*t*x1+t*t*x2,u*u*y0+2*u*t*y1+t*t*y2,r,r,c);}}
static bool star(float x,float y,float s){return sqrtf(fabsf(x)/(.8f*s))+sqrtf(fabsf(y)/s)<=1.0f;}
void FaceRenderer::eye(float x,float y,const FaceFrame& f){float op=f.expr.eye*(x<120+f.x?f.winkL:f.winkR);if(op<.12f){curve(x-22,y,x,y+(((int)f.mood<13?(f.mood==Mood::PETTED?-22:11):(f.mood==Mood::DREAMING||f.mood==Mood::WAKE_UP?11:-22))),x+22,y,7,INK);return;}float er=26*op,px=x+f.gazeX*(f.mood==Mood::TOUCH_ALERT?6:4),py=y+f.gazeY*4;int lo=(std::max)(offset,(int)ceilf(y-er)),hi=(std::min)(offset+STRIP-1,(int)floorf(y+er));int m=(int)f.mood;bool stars=m<=4||m==13||m==14||m==16||m==22||m==25||m==28||m==31||m==32||m==34||m>=37;for(int yy=lo;yy<=hi;yy++){float d=(yy-y)/er,w=26*sqrtf(fmaxf(0,1-d*d));int a=ceilf(x-w),b=floorf(x+w);line(a,b,yy,WHITE);if(m==35)continue;float q=f.pupil*f.pupil-(yy-py)*(yy-py);if(q<0)continue;float pw=sqrtf(q);a=(std::max)(a,(int)ceilf(px-pw));b=(std::min)(b,(int)floorf(px+pw));line(a,b,yy,INK);if(op<=.42f)continue;for(int xx=a;xx<=b;xx++){float dx=xx-px,dy=yy-py;bool hit=stars?(star(dx+8,dy+4,8)||star(dx-4,dy+11,3.5)||star(dx-4,dy-4,5)):((dx+5)*(dx+5)+(dy+6)*(dy+6)<=3.8f*3.8f);if(hit)line(xx,xx,yy,WHITE);}}if(m==35){float px0=x,py0=y;for(int i=1;i<=64;i++){float a=i/64.f*12.56637f+f.phase*3,r=i/64.f*22;float xx=x+cosf(a)*r,yy=y+sinf(a)*r;segment(px0,py0,xx,yy,4,INK);px0=xx;py0=yy;}}}
// Filled smile with quadratic top and bottom, sampled as a horizontal-width polygon.
void FaceRenderer::shape(float x,float y,float w,float h,uint16_t c){
 // Same quadratic smile silhouette as the V6 preview, filled by scanline.
 float xs[65],ys[65];int n=0;
 for(int i=0;i<=32;i++){float t=i/32.f,u=1-t;xs[n]=x-w+2*w*t;ys[n++]=y+18*u*t;}
 for(int i=1;i<=32;i++){float t=i/32.f,u=1-t;xs[n]=x+w-2*w*t;ys[n++]=y+2*h*u*t;}
 for(int yy=offset;yy<offset+STRIP;yy++){float a=1000,b=-1000;for(int i=0;i<n-1;i++){float y0=ys[i],y1=ys[i+1];if((y0<=yy&&yy<y1)||(y1<=yy&&yy<y0)){float xx=xs[i]+(xs[i+1]-xs[i])*(yy-y0)/(y1-y0);a=fminf(a,xx);b=fmaxf(b,xx);}}if(b>=a)line(ceilf(a),floorf(b),yy,c);}
}
void FaceRenderer::mouth(float x,float y,const FaceFrame& f){float sm=f.expr.smile,mo=f.expr.mouth;uint16_t pink=rgb(230,109,112);if(specialMouth(x,y,f))return;if(f.mood==Mood::TIRED_YAWNING){float r=2+21*f.opening;if(f.opening>.025f){ellipse(x,y,r,r,INK);if(r>5)ellipse(x,y+r*.46f,r*.58f,r*.3f,pink);}else curve(x-11,y,x,y+4,x+11,y,4,INK);return;}
 if(f.happy>.05f){float a=f.happy,w=SMILE_WIDTH;curve(x-mix(15,19*w,a),y,x+4*w*a,y+mix(sm*23,19,a),x+mix(15,21*w,a),y-8*a,mix(4.5,5.5,a),INK);if(a>.65f)curve(x+16*w,y-10,x+22*w,y-10,x+25*w,y-4,3,INK);return;}
 if(f.skeptical>.05f){curve(x-14,y,x,y+sm*23*(1-f.skeptical),x+14,y,5,INK);return;}
 if(mo>.13f){float mw=10+fmaxf(0,sm)*9,mh=mo*15;if(sm>.65f){shape(x,y-6,mw,28+mh,INK);ellipse(x,y+4+mh*.5f,mw*.43f,fmaxf(2,mh*.27f),pink);}else{ellipse(x,y,mw,mh,INK);if(mh>6)ellipse(x,y+mh*.45f,mw*.65f,mh*.31f,pink);}}else{float b=f.mood==Mood::SLEEPING?sinf(f.age*2.3f)*1.3f:0;curve(x-15,y+b,x,y+sm*23+b,x+15,y+b,f.mood==Mood::ANGRY?5.5f:4.5f,INK);}}
void FaceRenderer::effects(const FaceFrame& f){if(f.mood==Mood::SLEEPING){for(int j=0;j<3;j++){float u=fmodf(f.age+j*1.2f,3.6f)/3.6f;float x=158+u*10,y=94-u*36,s=11+u*13;float alpha=fminf(1,fminf(u*7,(1-u)*5));uint16_t c=blend(skin,rgb(85,83,45),alpha);float w=s*.6f;curve(x,y-s,x+w/2,y-s,x+w,y-s,2.5,c);curve(x+w,y-s,x+w/2,y-s/2,x,y,2.5,c);curve(x,y,x+w/2,y,x+w,y,2.5,c);}}
 if(f.mood==Mood::HOT){float u=fmodf(f.age,2.8f)/2.8f,v=fminf(1,u/.85f);float y=70+65*v*v*(3-2*v),a=fminf(1,fminf(u*9,(1-u)*7));uint16_t c=blend(skin,rgb(74,185,230),a);for(int yy=(std::max)(offset,(int)ceilf(y-14));yy<=(std::min)(offset+STRIP-1,(int)floorf(y+18));yy++){float d=yy-y,w=d<8?11*(d+14)/22:11*sqrtf(fmaxf(0,1-(d-8)*(d-8)/100));line(ceilf(192-w),floorf(192+w),yy,c);}ellipse(187,y+7,2.4,5,blend(skin,WHITE,a*.8f));}}
void FaceRenderer::render(const FaceFrame& f){float sleep=(f.mood==Mood::SLEEPING||f.mood==Mood::DREAMING)?.5f+.5f*sinf(f.age*2.3f):0;skin=rgb(lroundf(255-sleep*12),lroundf(229-f.expr.heat*88-sleep*15),lroundf(f.expr.heat*35));if(f.mood==Mood::COLD)skin=rgb(198,221,242);if(f.mood==Mood::OVERWATERED||f.mood==Mood::DIZZY)skin=rgb(215,223,101);if(f.mood==Mood::WAKE_UP){float u=fmaxf(0,fminf(1,(f.phase-.55f)/2));skin=rgb(233+22*u,213+16*u,32*(1-u));}for(int s=0;s<STRIPS;s++){offset=s*STRIP;sprite.fillSprite(INK);for(int y=offset;y<offset+STRIP;y++)line(left[y],right[y],y,skin);float dx=f.x,dy=f.y;for(int j=-1;j<=1;j+=2){float x=120+j*34+dx,y=105+dy,b=68+f.expr.brow+dy+(j<0?f.raiseL:f.raiseR);float tilt=f.expr.tilt*(-j)*12;curve(x-22,b-tilt,x,b-f.arch,x+22,b+tilt,8.5,INK);eye(x,y,f);}if(f.expr.blush>.02f){uint16_t c=blend(skin,rgb(239,148,117),f.expr.blush);ellipse(49+dx,137+dy,17,7,c);ellipse(191+dx,137+dy,17,7,c);}mouth(120+dx,149+dy,f);effects(f);objects(f);const uint8_t* data=static_cast<const uint8_t*>(sprite.getPointer());uint32_t h=2166136261u;for(int i=0;i<WIDTH*STRIP*2;i++)h=(h^data[i])*16777619u;if(!valid[s]||hashes[s]!=h){sprite.pushSprite(0,offset);hashes[s]=h;valid[s]=true;pushed++;}}}
